// The routine that puts a background's color rows back when the playfield rainbow stops (generated by generateBackgrounds in generators/bbasic.js as
// _background_rainbow_restore) tests the number of the background that is loaded and copies that background's rows with a "pfcolors:" statement, one after the
// other: each of them compiles to a test, a jump and the same fourteen instructions that set the data fetcher and call the coprocessor, with only the address of the
// rows different. This pass over the compiled assembly makes one copy of those instructions that gets the address of the rows from a table indexed by the
// number of the background (about 270 bytes less with five backgrounds). The rows themselves stay where the compiler put them (in the data bank).
//
// It does nothing (returns the assembly as it was) when the routine is not in the shape it expects.

const TEST = /^\.L\d+ ;;line \d+;;\s+if temp6\s+<>\s+(\d+) then goto _rainbowrestore_\d+\s*$/;
const ROWS_LOW = /^#<\(?(playfieldcolorL\d+)\)?$/;
const ROWS_HIGH = /^#\(\(>\(?(playfieldcolorL\d+)\)?\)?\s*&\s*\$0f\)\s*\|\s*\(\(\(>\(?(playfieldcolorL\d+)\)?\)?\s*\/\s*2\)\s*&\s*\$70\)$/i;

// The instructions (LDA and STA) of one block, between the line after its test and its end label, as [op, operand]; null when there is something else in it.
const instructionsOf = (lines, from, to) => {
  const list = [];
  for (let i = from; i < to; i++) {
    const text = lines[i];
    if (text.trim() === '' || /^\.L\d+ ;;/.test(text) || /^\.skipL\d+/.test(text) || /^\.condpart\d+/.test(text) || /^\s*;;/.test(text)) continue;
    // (What the test before the block is made of.)
    if (/^\s*(jmp \._rainbowrestore_\d+|BEQ \.skipL\d+|CMP #\d+|LDA temp6)\s*$/i.test(text)) continue;
    const match = /^\s*(LDA|STA)\s+(.+?)\s*$/i.exec(text);
    if (!match) return null;
    list.push([match[1].toUpperCase(), match[2]]);
  }
  return list;
};

export const compactRainbowRestore = (asm) => {
  const crlf = asm.includes('\r\n');
  const clean = asm.split('\n').map((line) => line.replace(/\r$/, ''));
  const start = clean.findIndex((line) => line === '._background_rainbow_restore');
  if (start === -1) return asm;
  const blocks = [];
  for (let i = start; i < clean.length && !(blocks.length && clean[i].startsWith('._background_') && i > blocks[0].at); i++) {
    const match = TEST.exec(clean[i]);
    if (!match) continue;
    const code = Number(match[1]);
    const end = clean.findIndex((line, k) => k > i && line === `._rainbowrestore_${code}`);
    if (end === -1 || (blocks.length && i < blocks[blocks.length - 1].end)) return asm;
    blocks.push({at: i, code, end});
  }
  if (blocks.length < 2) return asm;
  // The blocks are one after the other, with nothing else between them.
  for (let k = 1; k < blocks.length; k++) {
    const between = clean.slice(blocks[k - 1].end + 1, blocks[k].at).filter((line) => line.trim() !== '' && !/^\.L\d+ ;;|^\s*;;|^\.$/.test(line));
    if (between.length) return asm;
  }
  // The prologue gives how many numbers a background can have: the bits it adds up (1 + 2 + 4).
  const prologue = clean.slice(start, blocks[0].at).join('\n');
  const maxCode = [...prologue.matchAll(/(?:ADC #|INC temp6)(\d*)/gi)].reduce((sum, match) => sum + (match[1] === '' ? 1 : Number(match[1])), 0);
  if (!maxCode || maxCode > 15 || blocks.some((block) => block.code > maxCode)) return asm;
  // What each block does: the same fourteen instructions for all of them, but the address of the rows.
  const parsed = blocks.map((block) => {
    const list = instructionsOf(clean, block.at + 1, block.end);
    if (!list || list.length !== 14) return null;
    const low = ROWS_LOW.exec(list[4][1]);
    const high = ROWS_HIGH.exec(list[6][1]);
    if (!low || !high || high[1] !== low[1] || high[2] !== low[1] || list[4][0] !== 'LDA' || list[5].join(' ') !== 'STA PARAMETER' || list[6][0] !== 'LDA' ||
      list[7].join(' ') !== 'STA PARAMETER') return null;
    return {code: block.code, label: low[1], list};
  });
  if (parsed.some((entry) => !entry)) return asm;
  const fixed = (entry) => entry.list.filter((item, k) => k !== 4 && k !== 6).map((item) => item.join(' ')).join('|');
  if (new Set(parsed.map(fixed)).size !== 1) return asm;
  const sample = parsed[0].list;
  const lines = (list) => list.map(([op, operand]) => `\t${op} ${operand}`);
  const byCode = new Map(parsed.map((entry) => [entry.code, entry.label]));
  const labels = Array.from({length: maxCode}, (_, k) => byCode.get(k + 1));
  const replacement = [
    // (The tables are jumped over: they are data in the middle of the routine.)
    '\tJMP ._rainbowrestore_code',
    '._rainbowrestore_low',
    ...labels.map((label) => (label ? `\t.byte <${label}` : '\t.byte 0')),
    '._rainbowrestore_high',
    ...labels.map((label) => (label ? `\t.byte (((>${label}) & $0f) | (((>${label}) / 2) & $70))` : '\t.byte 0')),
    '._rainbowrestore_code',
    '\tLDX temp6',
    '\tBEQ ._rainbowrestore_done',
    `\tCPX #${maxCode + 1}`,
    '\tBCS ._rainbowrestore_done',
    '\tLDA ._rainbowrestore_high-1,X',
    '\tBEQ ._rainbowrestore_done',
    ...lines(sample.slice(0, 4)),
    '\tLDA ._rainbowrestore_low-1,X',
    '\tSTA PARAMETER',
    '\tLDA ._rainbowrestore_high-1,X',
    '\tSTA PARAMETER',
    ...lines(sample.slice(8)),
    '._rainbowrestore_done',
  ];
  const last = blocks[blocks.length - 1];
  const out = [...clean.slice(0, blocks[0].at), ...replacement, ...clean.slice(last.end + 1)];
  return out.join(crlf ? '\r\n' : '\n');
};
